// src/components/tags.js
import React from "react"
import { useStaticQuery, graphql, Link } from "gatsby"


const TagList = ({tag}) => {
    const data = useStaticQuery(graphql`
        query {
        allMarkdownRemark {
            group(field: { frontmatter: { tags: SELECT } }) {
            tag: fieldValue
            totalCount
            }
        }
        }
    `)
    const createStyle = (item) => {
        if (item.tag === tag) {
        return {
            'background-color': 'rgba(147, 51, 234, .8)' 
            }
        }
    }
    console.log('TagList', tag)
    return (
        <div className="w-full">
            <ul className="flex flex-wrap w-full">
                {data.allMarkdownRemark.group.map(({ tag, totalCount }) => (
                    <li key={tag} className="mr-1 mb-1 bg-[#000000] text-white block rounded-full py-[8px] px-[16px]" style={createStyle({tag})}>
                        <a href={`/categories/${tag}`} className="text-white">
                            {tag}
                        </a>
                    </li>
                ))}
            </ul>
        </div>
    )
}
export default TagList